/* Signature Galician Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Xosemar": "From Xose + mar (sea).", "Mariaria": "From Maria + ria (estuary).", "Antonrio": "From Anton + rio (river).", "Uxiamonte": "From Uxia + monte (mountain).", "Breoganmar": "From Breogan + mar.", "Iriabrisa": "From Iria + brisa (breeze).", "Xosemarez": "Signature surname in -ez style.", "Mariariaez": "Signature surname in -ez style.", "Antonrioez": "Signature surname in -ez style.", "Breoganez": "Signature surname in -ez style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Xosemar';
console.log(lookup(q));

